package com.rpgos.app

import android.database.sqlite.SQLiteDatabase

class AssetLiabilityStore(private val db: SQLiteDatabase, private val campaignId: String) {
    companion object { private const val REPLAY_LOCK_STRIPES=64; private val replayLocks=Array(REPLAY_LOCK_STRIPES){Any()} }
    init { require(campaignId.isNotBlank()) }

    fun registerAssetKind(d:AssetKindDefinition){AssetLiabilityPolicy.validateAssetKind(d);tx{OwnershipReferenceRegistry(db,campaignId).registerAssetKind(d.assetKindUid,d.provenance);val exists=count("SELECT COUNT(*) FROM asset_kind_definitions WHERE asset_kind_uid=?",arrayOf(d.assetKindUid))>0;if(!exists)db.execSQL("INSERT INTO asset_kind_definitions(asset_kind_uid,asset_class,display_name,world_pack_uid,definition_status,definition_version,provenance) VALUES(?,?,?,?,?,?,?)",arrayOf<Any?>(d.assetKindUid,d.assetClass.name,d.displayName,d.worldPackUid,d.status,d.version,d.provenance))else{val base="SELECT COUNT(*) FROM asset_kind_definitions WHERE asset_kind_uid=? AND asset_class=? AND display_name=? AND definition_status=? AND definition_version=? AND provenance=? AND ";val args=arrayOf(d.assetKindUid,d.assetClass.name,d.displayName,d.status,d.version.toString(),d.provenance);val matches=if(d.worldPackUid==null)count(base+"world_pack_uid IS NULL",args)else count(base+"world_pack_uid=?",args+d.worldPackUid);require(matches==1L){"asset kind UID semantic conflict"}}}}
    fun createAsset(a:AssetRecord):AssetRecord=stableUidWrite("asset:${a.assetKindUid}",a.assetUid){AssetLiabilityPolicy.validateAsset(a);require(a.campaignId==campaignId);existingAsset(a.ref)?.let{canonical->require(assetCreationMatches(canonical,a)){"asset UID semantic conflict"};return@stableUidWrite canonical};try{tx{existingAsset(a.ref)?.let{canonical->require(assetCreationMatches(canonical,a)){"asset UID semantic conflict"};return@tx};OwnershipReferenceRegistry(db,campaignId).registerAsset(a.ref,a.provenance);db.execSQL("INSERT INTO asset_records(campaign_id,asset_uid,asset_kind_uid,lifecycle_status,created_order,retired_order,source_event_uid,record_version,provenance,metadata_json) VALUES(?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(campaignId,a.assetUid,a.assetKindUid,a.lifecycle.name,a.createdOrder,a.retiredOrder,a.sourceEventUid,a.version,a.provenance,a.metadataJson))}}catch(t:Throwable){existingAsset(a.ref)?.let{canonical->if(assetCreationMatches(canonical,a))return@stableUidWrite canonical};throw t};requireAsset(a.ref)}
    fun retireAsset(ref:OwnedAssetRef,at:Long,lifecycle:AssetLifecycle,provenance:String):AssetRecord{require(lifecycle!=AssetLifecycle.ACTIVE&&provenance.isNotBlank());tx{val cur=requireAsset(ref);require(cur.lifecycle==AssetLifecycle.ACTIVE);val s=db.compileStatement("UPDATE asset_records SET lifecycle_status=?,retired_order=?,record_version=record_version+1 WHERE campaign_id=? AND asset_kind_uid=? AND asset_uid=? AND lifecycle_status='ACTIVE' AND record_version=?");s.use{it.bindString(1,lifecycle.name);it.bindLong(2,at);it.bindString(3,campaignId);it.bindString(4,ref.assetKindUid);it.bindString(5,ref.assetUid);it.bindLong(6,cur.version);require(it.executeUpdateDelete()==1){"stale asset lifecycle"}};OwnershipReferenceRegistry(db,campaignId).retireAsset(ref,provenance)};return requireAsset(ref)}
    fun recordValuation(v:AssetValuation):AssetValuation=stableUidWrite("valuation",v.valuationUid){AssetLiabilityPolicy.validateValuation(v);require(v.campaignId==campaignId);existingValuation(v.valuationUid)?.let{canonical->require(canonical==v){"valuation UID semantic conflict"};return@stableUidWrite canonical};try{db.execSQL("INSERT INTO asset_valuations(campaign_id,valuation_uid,asset_kind_uid,asset_uid,currency_uid,amount_minor,valuation_type,effective_order,valid_until_order,source_event_uid,confidence_ppm,valuation_version,provenance) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(campaignId,v.valuationUid,v.asset.assetKindUid,v.asset.assetUid,v.currencyUid,v.amountMinor,v.valuationType.name,v.effectiveOrder,v.validUntilOrder,v.sourceEventUid,v.confidencePpm,v.version,v.provenance))}catch(t:Throwable){existingValuation(v.valuationUid)?.let{canonical->if(canonical==v)return@stableUidWrite canonical};throw t};requireNotNull(existingValuation(v.valuationUid))}
    fun createObligation(o:ObligationRecord,initialStatusEventUid:String):ObligationRecord=stableUidWrite("obligation",o.obligationUid){AssetLiabilityPolicy.validateObligation(o);require(o.campaignId==campaignId&&initialStatusEventUid.isNotBlank());existingObligation(o.obligationUid)?.let{canonical->require(canonical==o&&initialStatusMatches(o,initialStatusEventUid)){"obligation UID semantic conflict"};return@stableUidWrite canonical};try{tx{existingObligation(o.obligationUid)?.let{canonical->require(canonical==o&&initialStatusMatches(o,initialStatusEventUid)){"obligation UID semantic conflict"};return@tx};db.execSQL("INSERT INTO obligation_records(campaign_id,obligation_uid,obligation_type_uid,obligation_class,obligor_kind_uid,obligor_uid,beneficiary_kind_uid,beneficiary_uid,currency_uid,principal_minor,asset_kind_uid,asset_uid,created_order,due_order,valid_until_order,source_event_uid,source_contract_uid,record_version,provenance,metadata_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(campaignId,o.obligationUid,o.obligationTypeUid,o.obligationClass.name,o.obligor.ownerKindUid,o.obligor.ownerUid,o.beneficiary.ownerKindUid,o.beneficiary.ownerUid,o.currencyUid,o.principalMinor,o.asset?.assetKindUid,o.asset?.assetUid,o.createdOrder,o.dueOrder,o.validUntilOrder,o.sourceEventUid,o.sourceContractUid,o.version,o.provenance,o.metadataJson));db.execSQL("INSERT INTO obligation_status_history(campaign_id,status_event_uid,obligation_uid,status,effective_order,source_event_uid,provenance) VALUES(?,?,?,'ACTIVE',?,?,?)",arrayOf<Any?>(campaignId,initialStatusEventUid,o.obligationUid,o.createdOrder,o.sourceEventUid,o.provenance))}}catch(t:Throwable){existingObligation(o.obligationUid)?.let{canonical->if(canonical==o&&initialStatusMatches(o,initialStatusEventUid))return@stableUidWrite canonical};throw t};requireNotNull(existingObligation(o.obligationUid))}
    fun settle(s:ObligationSettlement):ObligationSettlement=stableUidWrite("settlement",s.settlementUid){require(s.campaignId==campaignId&&s.settlementUid.isNotBlank()&&s.obligationUid.isNotBlank()&&s.provenance.isNotBlank());require(s.amountMinor==null||s.amountMinor>0);existingSettlement(s.settlementUid)?.let{canonical->require(canonical==s){"settlement UID semantic conflict"};return@stableUidWrite canonical};try{db.execSQL("INSERT INTO obligation_settlements(campaign_id,settlement_uid,obligation_uid,settlement_kind,amount_minor,financial_transaction_uid,ownership_operation_uid,effective_order,source_event_uid,provenance) VALUES(?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(campaignId,s.settlementUid,s.obligationUid,s.kind.name,s.amountMinor,s.financialTransactionUid,s.ownershipOperationUid,s.effectiveOrder,s.sourceEventUid,s.provenance))}catch(t:Throwable){existingSettlement(s.settlementUid)?.let{canonical->if(canonical==s)return@stableUidWrite canonical};throw t};requireNotNull(existingSettlement(s.settlementUid))}
    fun changeObligationStatus(obligationUid:String,eventUid:String,status:ObligationStatus,at:Long,provenance:String,sourceEventUid:String?=null)=stableUidWrite("status",eventUid){require(obligationUid.isNotBlank()&&eventUid.isNotBlank()&&provenance.isNotBlank());if(statusEventExists(eventUid)){require(statusEventMatches(obligationUid,eventUid,status,at,provenance,sourceEventUid)){"status event UID semantic conflict"};return@stableUidWrite};try{db.execSQL("INSERT INTO obligation_status_history(campaign_id,status_event_uid,obligation_uid,status,effective_order,source_event_uid,provenance) VALUES(?,?,?,?,?,?,?)",arrayOf<Any?>(campaignId,eventUid,obligationUid,status.name,at,sourceEventUid,provenance))}catch(t:Throwable){if(statusEventExists(eventUid)&&statusEventMatches(obligationUid,eventUid,status,at,provenance,sourceEventUid))return@stableUidWrite;throw t}}
    fun outstandingMinor(uid:String,at:Long=Long.MAX_VALUE):Long?{val principal=db.rawQuery("SELECT principal_minor FROM obligation_records WHERE campaign_id=? AND obligation_uid=?",arrayOf(campaignId,uid)).use{c->if(!c.moveToFirst())error("obligation not found")else if(c.isNull(0))return null else c.getLong(0)};var paid=0L;db.rawQuery("SELECT amount_minor FROM obligation_settlements WHERE campaign_id=? AND obligation_uid=? AND amount_minor IS NOT NULL AND effective_order<=? ORDER BY effective_order,settlement_uid",arrayOf(campaignId,uid,at.toString())).use{c->while(c.moveToNext())paid=Math.addExact(paid,c.getLong(0))};return Math.subtractExact(principal,paid)}
    fun currentStatus(uid:String,at:Long=Long.MAX_VALUE):ObligationStatus?=db.rawQuery("SELECT status FROM obligation_status_history WHERE campaign_id=? AND obligation_uid=? AND effective_order<=? ORDER BY effective_order DESC,status_event_uid DESC LIMIT 1",arrayOf(campaignId,uid,at.toString())).use{c->if(c.moveToFirst())ObligationStatus.valueOf(c.getString(0))else null}
    fun addEncumbrance(uid:String,asset:OwnedAssetRef,obligationUid:String,typeUid:String,priority:Int,at:Long,provenance:String)=stableUidWrite("encumbrance",uid){require(uid.isNotBlank()&&typeUid.isNotBlank()&&provenance.isNotBlank());if(encumbranceExists(uid)){require(encumbranceCreationMatches(uid,asset,obligationUid,typeUid,priority,at,provenance)){"encumbrance UID semantic conflict"};return@stableUidWrite};try{db.execSQL("INSERT INTO asset_encumbrances(campaign_id,encumbrance_uid,asset_kind_uid,asset_uid,obligation_uid,encumbrance_type_uid,priority,valid_from_order,record_version,provenance) VALUES(?,?,?,?,?,?,?,?,1,?)",arrayOf<Any?>(campaignId,uid,asset.assetKindUid,asset.assetUid,obligationUid,typeUid,priority,at,provenance))}catch(t:Throwable){if(encumbranceExists(uid)&&encumbranceCreationMatches(uid,asset,obligationUid,typeUid,priority,at,provenance))return@stableUidWrite;throw t}}
    fun releaseEncumbrance(uid:String,at:Long,provenance:String){require(uid.isNotBlank()&&provenance.isNotBlank());val s=db.compileStatement("UPDATE asset_encumbrances SET released_order=?,record_version=record_version+1,release_provenance=? WHERE campaign_id=? AND encumbrance_uid=? AND released_order IS NULL");s.use{it.bindLong(1,at);it.bindString(2,provenance);it.bindString(3,campaignId);it.bindString(4,uid);require(it.executeUpdateDelete()==1){"active encumbrance not found"}}}
    fun netWorth(p:OwnershipOwnerRef,currency:String,at:Long):NetWorthProjection{OwnershipPolicy.validateOwner(p);require(currency.isNotBlank());var assets=0L;var missing=0;db.rawQuery("SELECT r.asset_kind_uid,r.asset_uid,r.share_units FROM ownership_records r JOIN asset_records a ON a.campaign_id=r.campaign_id AND a.asset_kind_uid=r.asset_kind_uid AND a.asset_uid=r.asset_uid WHERE r.campaign_id=? AND r.owner_kind_uid=? AND r.owner_uid=? AND r.ownership_type_uid=? AND r.valid_from_order<=? AND (r.valid_until_order IS NULL OR ?<r.valid_until_order) AND a.created_order<=? AND (a.retired_order IS NULL OR ?<a.retired_order)",arrayOf(campaignId,p.ownerKindUid,p.ownerUid,OWNERSHIP_TYPE_ECONOMIC,at.toString(),at.toString(),at.toString(),at.toString())).use{c->while(c.moveToNext()){val ref=OwnedAssetRef(c.getString(0),c.getString(1));if(ref.assetKindUid==ASSET_KIND_RECEIVABLE&&hasLinkedBeneficiaryObligation(ref,p,currency,at))continue;val value=valuationAt(ref,currency,at);if(value==null)missing++else assets=Math.addExact(assets,AssetLiabilityPolicy.exactShareValue(value,c.getLong(2)))}};val cash=cashAt(p,currency,at);var receivables=0L;var liabilities=0L;db.rawQuery("SELECT obligation_uid,obligor_kind_uid,obligor_uid,beneficiary_kind_uid,beneficiary_uid FROM obligation_records WHERE campaign_id=? AND currency_uid=? AND created_order<=? AND (valid_until_order IS NULL OR ?<valid_until_order)",arrayOf(campaignId,currency,at.toString(),at.toString())).use{c->while(c.moveToNext()){val uid=c.getString(0);val st=currentStatus(uid,at);if(st!=null&&st !in setOf(ObligationStatus.SETTLED,ObligationStatus.CANCELLED,ObligationStatus.EXPIRED)){val out=outstandingMinor(uid,at)?:0L;if(c.getString(1)==p.ownerKindUid&&c.getString(2)==p.ownerUid)liabilities=Math.addExact(liabilities,out);if(c.getString(3)==p.ownerKindUid&&c.getString(4)==p.ownerUid)receivables=Math.addExact(receivables,out)}}};val net=Math.subtractExact(Math.addExact(Math.addExact(assets,cash),receivables),liabilities);return NetWorthProjection(campaignId,p,currency,at,assets,cash,receivables,liabilities,net,missing)}
    fun assetCount()=count("SELECT COUNT(*) FROM asset_records WHERE campaign_id=?",arrayOf(campaignId));fun obligationCount()=count("SELECT COUNT(*) FROM obligation_records WHERE campaign_id=?",arrayOf(campaignId))
    private fun hasLinkedBeneficiaryObligation(a:OwnedAssetRef,p:OwnershipOwnerRef,currency:String,at:Long)=count("SELECT COUNT(*) FROM obligation_records WHERE campaign_id=? AND asset_kind_uid=? AND asset_uid=? AND beneficiary_kind_uid=? AND beneficiary_uid=? AND currency_uid=? AND created_order<=? AND (valid_until_order IS NULL OR ?<valid_until_order)",arrayOf(campaignId,a.assetKindUid,a.assetUid,p.ownerKindUid,p.ownerUid,currency,at.toString(),at.toString()))>0
    private fun valuationAt(a:OwnedAssetRef,currency:String,at:Long):Long?=db.rawQuery("SELECT amount_minor FROM asset_valuations WHERE campaign_id=? AND asset_kind_uid=? AND asset_uid=? AND currency_uid=? AND effective_order<=? AND (valid_until_order IS NULL OR ?<valid_until_order) ORDER BY effective_order DESC,valuation_uid DESC LIMIT 1",arrayOf(campaignId,a.assetKindUid,a.assetUid,currency,at.toString(),at.toString())).use{c->if(c.moveToFirst())c.getLong(0)else null}
    private fun cashAt(p:OwnershipOwnerRef,currency:String,at:Long):Long{var total=0L;db.rawQuery("SELECT account_uid FROM financial_accounts WHERE campaign_id=? AND holder_kind_uid=? AND holder_uid=? AND currency_uid=? AND opened_order<=? AND (closed_order IS NULL OR ?<closed_order)",arrayOf(campaignId,p.ownerKindUid,p.ownerUid,currency,at.toString(),at.toString())).use{a->while(a.moveToNext()){val account=a.getString(0);var bal=0L;db.rawQuery("SELECT from_account_uid,to_account_uid,amount_minor FROM financial_ledger_transactions WHERE campaign_id=? AND (from_account_uid=? OR to_account_uid=?) AND effective_order<=? ORDER BY effective_order,financial_transaction_uid",arrayOf(campaignId,account,account,at.toString())).use{t->while(t.moveToNext()){if(!t.isNull(0)&&t.getString(0)==account)bal=Math.subtractExact(bal,t.getLong(2));if(!t.isNull(1)&&t.getString(1)==account)bal=Math.addExact(bal,t.getLong(2))}};total=Math.addExact(total,bal)}};return total}
    private fun existingAsset(a:OwnedAssetRef):AssetRecord?=db.rawQuery("SELECT lifecycle_status,created_order,retired_order,source_event_uid,record_version,provenance,metadata_json FROM asset_records WHERE campaign_id=? AND asset_kind_uid=? AND asset_uid=?",arrayOf(campaignId,a.assetKindUid,a.assetUid)).use{c->if(!c.moveToFirst())null else AssetRecord(campaignId,a.assetUid,a.assetKindUid,c.getLong(1),c.getString(5),AssetLifecycle.valueOf(c.getString(0)),if(c.isNull(2))null else c.getLong(2),if(c.isNull(3))null else c.getString(3),c.getLong(4),if(c.isNull(6))null else c.getString(6))}
    private fun assetCreationMatches(c:AssetRecord,a:AssetRecord)=c.campaignId==a.campaignId&&c.assetUid==a.assetUid&&c.assetKindUid==a.assetKindUid&&c.createdOrder==a.createdOrder&&c.sourceEventUid==a.sourceEventUid&&c.provenance==a.provenance&&c.metadataJson==a.metadataJson
    private fun existingValuation(uid:String):AssetValuation?=db.rawQuery("SELECT asset_kind_uid,asset_uid,currency_uid,amount_minor,valuation_type,effective_order,valid_until_order,source_event_uid,confidence_ppm,valuation_version,provenance FROM asset_valuations WHERE campaign_id=? AND valuation_uid=?",arrayOf(campaignId,uid)).use{c->if(!c.moveToFirst())null else AssetValuation(campaignId,uid,OwnedAssetRef(c.getString(0),c.getString(1)),c.getString(2),c.getLong(3),ValuationType.valueOf(c.getString(4)),c.getLong(5),c.getString(10),if(c.isNull(6))null else c.getLong(6),if(c.isNull(7))null else c.getString(7),if(c.isNull(8))null else c.getLong(8),c.getLong(9))}
    private fun existingObligation(uid:String):ObligationRecord?=db.rawQuery("SELECT obligation_type_uid,obligation_class,obligor_kind_uid,obligor_uid,beneficiary_kind_uid,beneficiary_uid,currency_uid,principal_minor,asset_kind_uid,asset_uid,created_order,due_order,valid_until_order,source_event_uid,source_contract_uid,record_version,provenance,metadata_json FROM obligation_records WHERE campaign_id=? AND obligation_uid=?",arrayOf(campaignId,uid)).use{c->if(!c.moveToFirst())null else ObligationRecord(campaignId,uid,c.getString(0),ObligationClass.valueOf(c.getString(1)),OwnershipOwnerRef(c.getString(2),c.getString(3)),OwnershipOwnerRef(c.getString(4),c.getString(5)),c.getLong(10),c.getString(16),if(c.isNull(6))null else c.getString(6),if(c.isNull(7))null else c.getLong(7),if(c.isNull(8))null else OwnedAssetRef(c.getString(8),c.getString(9)),if(c.isNull(11))null else c.getLong(11),if(c.isNull(12))null else c.getLong(12),if(c.isNull(13))null else c.getString(13),if(c.isNull(14))null else c.getString(14),c.getLong(15),if(c.isNull(17))null else c.getString(17))}
    private fun existingSettlement(uid:String):ObligationSettlement?=db.rawQuery("SELECT obligation_uid,settlement_kind,amount_minor,financial_transaction_uid,ownership_operation_uid,effective_order,source_event_uid,provenance FROM obligation_settlements WHERE campaign_id=? AND settlement_uid=?",arrayOf(campaignId,uid)).use{c->if(!c.moveToFirst())null else ObligationSettlement(campaignId,uid,c.getString(0),SettlementKind.valueOf(c.getString(1)),c.getLong(5),c.getString(7),if(c.isNull(2))null else c.getLong(2),if(c.isNull(3))null else c.getString(3),if(c.isNull(4))null else c.getString(4),if(c.isNull(6))null else c.getString(6))}
    private fun initialStatusMatches(o:ObligationRecord,eventUid:String):Boolean{val base="SELECT COUNT(*) FROM obligation_status_history WHERE campaign_id=? AND status_event_uid=? AND obligation_uid=? AND status='ACTIVE' AND effective_order=? AND provenance=? AND ";val args=arrayOf(campaignId,eventUid,o.obligationUid,o.createdOrder.toString(),o.provenance);return if(o.sourceEventUid==null)count(base+"source_event_uid IS NULL",args)==1L else count(base+"source_event_uid=?",args+o.sourceEventUid)==1L}
    private fun statusEventExists(uid:String)=count("SELECT COUNT(*) FROM obligation_status_history WHERE campaign_id=? AND status_event_uid=?",arrayOf(campaignId,uid))>0
    private fun statusEventMatches(obligationUid:String,eventUid:String,status:ObligationStatus,at:Long,provenance:String,sourceEventUid:String?):Boolean{val base="SELECT COUNT(*) FROM obligation_status_history WHERE campaign_id=? AND status_event_uid=? AND obligation_uid=? AND status=? AND effective_order=? AND provenance=? AND ";val args=arrayOf(campaignId,eventUid,obligationUid,status.name,at.toString(),provenance);return if(sourceEventUid==null)count(base+"source_event_uid IS NULL",args)==1L else count(base+"source_event_uid=?",args+sourceEventUid)==1L}
    private fun encumbranceExists(uid:String)=count("SELECT COUNT(*) FROM asset_encumbrances WHERE campaign_id=? AND encumbrance_uid=?",arrayOf(campaignId,uid))>0
    private fun encumbranceCreationMatches(uid:String,asset:OwnedAssetRef,obligationUid:String,typeUid:String,priority:Int,at:Long,provenance:String)=count("SELECT COUNT(*) FROM asset_encumbrances WHERE campaign_id=? AND encumbrance_uid=? AND asset_kind_uid=? AND asset_uid=? AND obligation_uid=? AND encumbrance_type_uid=? AND priority=? AND valid_from_order=? AND provenance=?",arrayOf(campaignId,uid,asset.assetKindUid,asset.assetUid,obligationUid,typeUid,priority.toString(),at.toString(),provenance))==1L
    private fun requireAsset(a:OwnedAssetRef):AssetRecord=requireNotNull(existingAsset(a)){"Phase14 asset not found"}
    private fun<T>stableUidWrite(domain:String,uid:String,block:()->T):T=synchronized(replayLock(domain,uid)){block()}
    private fun replayLock(domain:String,uid:String):Any{val key="$campaignId|$domain|$uid";return replayLocks[(key.hashCode() and Int.MAX_VALUE)%REPLAY_LOCK_STRIPES]}
    private fun count(sql:String,args:Array<out String?>)=db.rawQuery(sql,args).use{c->c.moveToFirst();c.getLong(0)}
    private fun tx(block:()->Unit){if(db.inTransaction()){block();return};db.beginTransaction();try{block();db.setTransactionSuccessful()}finally{db.endTransaction()}}
}
